    function getSocials(data) {
        const socials = {};
        if (data.radio_facebook_url) socials.facebook = data.radio_facebook_url;
        if (data.radio_youtube) socials.youtube = data.radio_youtube;
        if (data.radio_instagram) socials.instagram = data.radio_instagram;
        if (data.radio_whatsapp) socials.whatsapp = `https://wa.me/+${data.radio_whatsapp}`;
        
        // Nuevas redes (Solo si el campo no está vacío)
        if (data.radio_menu_nicio) socials.twitch = data.radio_menu_nicio;
        if (data.radio_menu_programas) socials.kick = data.radio_menu_programas;
        if (data.radio_menu_noticias) socials.tiktok = data.radio_menu_noticias;
        if (data.radio_menu_mensajes) socials.x = data.radio_menu_mensajes;
        
        if (data.radio_onesignal_id && data.radio_onesignal_id.trim() !== "") {
            socials.telegram = `https://t.me/${data.radio_onesignal_id}`;
        }
        return socials;
    }

    function getApps(data) {
        const apps = {};
        if (data.radio_android_url) apps.android = data.radio_android_url;
        if (data.radio_ios_url) apps.ios = data.radio_ios_url;
        return apps;
    }

    function timeAgo(date) {
        const getSecondsDiff = timestamp => (Date.now() - timestamp) / 1000;
        const DATE_UNITS = { day: 86400, hour: 3600, minute: 60, second: 1 };
        const getUnitAndValueDate = secondsElapsed => {
            for (const [unit, secondsInUnit] of Object.entries(DATE_UNITS)) {
                if (secondsElapsed >= secondsInUnit || unit === 'second') {
                    const value = Math.floor(secondsElapsed / secondsInUnit) * -1;
                    return { value, unit };
                }
            }
        };
        const getTimeAgo = timestamp => {
            const rtf = new Intl.RelativeTimeFormat();
            const secondsElapsed = getSecondsDiff(timestamp);
            const { value, unit } = getUnitAndValueDate(secondsElapsed);
            return rtf.format(value, unit);
        };
        const reference = new Date(date);
        return getTimeAgo(reference);
    }

    function getStationData(data, baseUrl, isMultiStream = false) {
        // Función interna para limpiar el texto "null"
        const limpiar = (txt) => (txt === "null" || !txt) ? "" : txt;

        return {
            name: limpiar(isMultiStream ? data.multiradio_nombre : data.radio_nombre),
            description: limpiar(isMultiStream ? data.multiradio_descripcion : (data.radio_onesignal_apirest || data.radio_slogan)),
            stream_url: limpiar(isMultiStream ? data.multiradio_url : data.radio_url),
            tv_url: limpiar(isMultiStream ? data.multiradio_tvstream : data.radio_video),
            picture: `${baseUrl}${data.multiradio_imagen || data.radio_fondo}`,
            background: isMultiStream ? `${baseUrl}${data.multiradio_imagen}` : `${baseUrl}${data.radio_splash}`,
            api: isMultiStream ? data.multiradio_api : data.radio_menu_nicio,
            fondo_color: data.radio_fondo_color || '#121212',
            mostrar_oyentes: data.radio_facebook_id || "SI"
        };
    }

    function loadImage(src) {
        return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = reject;
            img.src = src;
        });
    }

    function slideUpImageTransition(container, src) {
        const img = document.createElement('img');
        const size = container.clientHeight;
        img.src = src;
        img.width = size;
        img.height = size;
        container.appendChild(img);
        const firstImg = container.querySelector('img:first-child');
        firstImg.style.marginLeft = `-${size}px`;
        firstImg.addEventListener('transitionend', () => {
            const allImgExcLast = container.querySelectorAll('img:not(:last-child)');
            allImgExcLast.forEach(img => img.remove());
        }, { once: true });
    }

    function fadeImageTransition(container, src) {
        container.style.opacity = 0;
        container.addEventListener('transitionend', () => {
            container.src = src;
            container.style.opacity = 0.2;
            container.addEventListener('transitionend', () => {
                container.removeAttribute('style');
            }, { once: true });
        });
    }

    function createProxyImage(src) {
        return new Promise((resolve, reject) => {
            const img = document.createElement('img');
            img.crossOrigin = 'Anonymous';
            img.src = `https://images.weserv.nl/?url=${src}`;
            img.onload = () => resolve(img);
            img.onerror = reject;
        });
    }

    function setAccentColor(image, colorThief) {
        const metaThemeColor = document.querySelector('meta[name=theme-color]');
        const applyColor = () => {
            const color = `rgb(${colorThief.getColor(image)})`;
            document.querySelector('html').style.setProperty('--player-accent', color);
            if (metaThemeColor) metaThemeColor.setAttribute('content', color);
        };
        if (image.complete) applyColor();
        else image.addEventListener('load', applyColor);
    }

    const setAttributes = (element, attributes) => {
        for (const key in attributes) element.setAttribute(key, attributes[key]);
    };

    function createEmbed({ url, params = {} }) {
        const $iframe = document.createElement('iframe');
        $iframe.src = url;
        $iframe.frameborder = 0;
        setAttributes($iframe, params);
        return $iframe;
    }

    async function getVideoInfo(videoId) {
        const data = await fetch(`https://noembed.com/embed?dataType=json&url=https://www.youtube.com/watch?v=${videoId}`);
        return data.json();
    }

    // --- FUNCIÓN GENERADORA DEL LINK DE SHARE.PHP ---
