        // --- CASO AZURACAST (Tu servidor) ---
        if (streamUrl.includes('/listen/')) {
            try {
                const urlParts = streamUrl.split('/');
                const stationShortcode = urlParts[urlParts.indexOf('listen') + 1];
                const azuraApi = `https://orbitalvip.site/api/nowplaying_static/${stationShortcode}.json`;

                const response = await fetch(azuraApi);
                const data = await response.json();

                return {
                    title: data.now_playing.song.title,
                    artist: data.now_playing.song.artist,
                    song: data.now_playing.song.text,
                    listeners: data.listeners.total, // Aquí sí hay datos reales
                    song_history: data.song_history.map(item => ({ song: { title: item.song.title, artist: item.song.artist } }))
                };
            } catch (error) { 
                console.error('Error Azura:', error);
                return { listeners: 0 }; // Si falla, devolvemos 0
            }
        }

        // --- CASO OTRAS RADIOS (Zeno, Shoutcast externo, etc.) ---
        // Como no podemos leer los oyentes de otros servidores fácilmente, devolvemos 0
        const jsonUri = `https://api.turadio.online/mi_api.php?url=${encodeURIComponent(streamUrl)}`;
